/*
 * Sphinx stylesheet -- nonav theme.
 */

/* -- main layout ----------------------------------------------------------- */

div.clearer {
    clear: both;
}

a:link {
    color: #3333ff;
    text-decoration: underline;
}

a:visited {
    color: #551a8b;
    text-decoration: underline;
}

img {
    border: 0;
    max-width: 100%;
}

/* -- relbar ---------------------------------------------------------------- */

div.related {
    width: 100%;
    font-family: sans-serif;
    font-size: 90%;
}

div.related h3 {
    display: none;
}

div.related ul {
    margin: 0;
    padding: 0 0 0 10px;
    list-style: none;
}

div.related li {
    display: inline;
}

div.related li.right {
    float: right;
    margin-right: 5px;
}

/* -- sidebar --------------------------------------------------------------- */

div.sphinxsidebarwrapper {
    padding: 10px 5px 0 10px;
}

div.sphinxsidebar {
    float: left;
    width: 230px;
    margin-left: -100%;
    font-size: 90%;
}

div.sphinxsidebar ul {
    list-style: none;
}

div.sphinxsidebar ul ul,
